import {KEY,uid,money,days,validate,balances,seed} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let trips=[],current='lisbon',tab='Overview',day='',filter='All ideas',balanceView=false,user=null;
try{const raw=localStorage.getItem(KEY);trips=raw?JSON.parse(raw):[seed()];if(!Array.isArray(trips)||!trips.length)throw Error();}catch{trips=[seed()];}
const trip=()=>trips.find(t=>t.id===current)||trips[0];
const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const time=t=>new Date('2000-01-01T'+t).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(trips));}catch{toast('Storage is unavailable. Keep this tab open to retain your changes.');}render();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000);}
const avatars=t=>`<div class="avatars">${t.people.slice(0,6).map(n=>`<span class="avatar" title="${esc(n)}">${esc(n[0])}</span>`).join('')}</div>`;
function plans(t,date){const a=t.plans.filter(p=>!date||p.date===date).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return a.length?a.map(p=>`<div class="plan"><time>${time(p.time)}</time><span class="icon">${p.type==='Travel'?'↗':p.type==='Food & drink'?'♧':'☀'}</span><button data-action="detail" data-id="${p.id}"><h3>${esc(p.title)}</h3><span class="muted small">${esc(p.location)}</span><br><span class="tag">${esc(p.type)}</span></button></div>`).join(''):'<div class="empty">A day full of possibilities.<br>Add your first plan.</div>';}
function render(){const t=trip();if(!day||day<t.start||day>t.end)day=t.start;const total=t.expenses.reduce((s,e)=>s+e.amount,0),done=t.checklist.filter(c=>c.done).length;
$('#app').innerHTML=`<header><button class="brand link" data-action="trips">roam<span>✳</span></button><div class="toplinks"><span class="muted small">Good trips start together.</span><button data-action="auth">${user?'Account':'Sign in to save & share'} ↗</button></div></header><aside><p class="eyebrow">Your next adventure</p><button data-action="trips" class="${tab==='My trips'?'active':''}">▦ &nbsp; My trips</button><button data-action="open" data-id="${t.id}" class="${tab!=='My trips'?'active':''}">☀ &nbsp; ${esc(t.destination.split(',')[0])}</button><button data-action="new">＋ &nbsp; Plan a new trip</button><div class="side-note"><span style="font-size:28px">✳</span><p><strong>Less planning.<br>More living.</strong></p><span class="muted small">The best part of a trip?<br>Who you go with.</span></div><div class="side-bottom"><span class="avatar">D</span> &nbsp; Drew <span class="muted small"> · Demo traveler</span></div></aside><main>${tab==='My trips'?`<div class="section-head"><div><p class="eyebrow">A world of possibilities</p><h1>My trips</h1><p class="muted">Big adventures. Little escapes. All in one place.</p></div><button class="primary" data-action="new">＋ Plan a new trip</button></div><div class="tripcards">${trips.map(x=>`<button data-action="open" data-id="${x.id}"><span class="eyebrow">${esc(x.destination)}</span><h2 style="margin-top:20px">${esc(x.name)}</h2><p class="muted">${fmt(x.start)} – ${fmt(x.end)}, ${x.start.slice(0,4)}</p><span>${x.people.length} travelers · ${money(x.budget)} budget</span></button>`).join('')}</div>`:`<div class="crumb"><button class="link small" data-action="trips">My trips</button> / &nbsp; ${esc(t.destination.split(',')[0])}</div><section class="hero"><button class="edit" data-action="edit">✎ &nbsp; Edit trip details</button><div><span class="pill">THE NEXT CHAPTER</span><h1>${esc(t.name)}</h1><p>⌖ ${esc(t.destination)} &nbsp; · &nbsp; ${fmt(t.start)} – ${fmt(t.end)}, ${t.start.slice(0,4)}</p></div></section><div class="tripbar"><div class="roster">${avatars(t)}<span><strong>${t.people.length} travelers</strong><br><span class="muted small">One great adventure</span></span></div><button data-action="invite">♧ &nbsp; Invite friends</button></div><nav>${['Overview','Itinerary','Ideas & voting','Expenses','Trip chat'].map((n,i)=>`<button data-action="tab" data-id="${n}" class="${n===tab?'active':''}">${['▦','☷','♧','＄','☏'][i]} &nbsp; ${n}</button>`).join('')}</nav>${tab==='Overview'?`<div class="section-head"><div><h2>It's all coming together.</h2><span class="muted">A little planning now, a lot of memories later.</span></div><span class="tag">✳ Device-local demo</span></div><div class="grid"><section class="card"><div class="section-head"><h3>The plan so far</h3><button class="link small" data-action="tab" data-id="Itinerary">View itinerary →</button></div><p class="eyebrow">Day 1 · ${fmt(t.start)}</p>${plans(t,t.start)}</section><section class="card"><h3>Adventure checklist</h3><span class="muted small">${done} of ${t.checklist.length} complete</span><progress value="${done}" max="${t.checklist.length}"></progress>${t.checklist.map((c,i)=>`<label class="check ${c.done?'done':''}"><input type="checkbox" data-check="${i}" ${c.done?'checked':''}><span>${esc(c.title)}</span></label>`).join('')}</section><section class="card"><div class="section-head"><h3>Made for the whole crew</h3><button class="link small" data-action="tab" data-id="Ideas & voting">Explore ideas →</button></div><p class="muted">A day trip? A hidden café? Share the things you can't wait to do.</p><button data-action="idea">＋ Share an idea</button></section><section class="card"><h3>A little budget check-in</h3><p><strong style="font-size:28px">${money(total)}</strong> <span class="muted">of ${money(t.budget)}</span></p><progress value="${Math.min(total,t.budget)}" max="${t.budget||1}"></progress><span class="muted small">${money(t.budget-total)} left for making memories</span></section></div>`:tab==='Itinerary'?`<div class="section-head"><div><h2>A little structure. Room to wander.</h2><span class="muted">Your days, beautifully unhurried.</span></div><button class="primary" data-action="plan">＋ Add a plan</button></div><div class="days">${Array.from({length:days(t.start,t.end)},(_,i)=>{const d=new Date(Date.parse(t.start)+i*86400000).toISOString().slice(0,10);return `<button data-action="day" data-id="${d}" class="${day===d?'active':''}">Day ${i+1}<br><small>${fmt(d)}</small></button>`;}).join('')}</div><section class="card"><h3>${fmt(day)} · ${t.plans.filter(p=>p.date===day).length} plans</h3>${plans(t,day)}</section>`:tab==='Ideas & voting'?`<div class="section-head"><div><h2>Good ideas deserve company.</h2><span class="muted">Dream it up. Put it to a vote.</span></div><button class="primary" data-action="idea">＋ Share an idea</button></div><div class="filters">${['All ideas','Experiences','Stays','Food & drink'].map(c=>`<button data-action="filter" data-id="${c}" class="${c===filter?'active':''}">${c}</button>`).join('')}</div><div class="ideas">${t.ideas.filter(i=>filter==='All ideas'||i.category===filter).map(i=>`<article class="card idea"><div class="idea-art">${i.category==='Stays'?'⌂':i.category==='Food & drink'?'☕':'☀'}</div><span class="eyebrow">${esc(i.category)}</span><h3 style="margin-top:12px">${esc(i.title)}</h3><p>${esc(i.description)}</p><button data-action="vote" data-id="${i.id}" aria-pressed="${i.voted}" class="vote ${i.voted?'selected':''}">↑ &nbsp; ${i.votes} votes ${i.voted?'· Voted':''}</button></article>`).join('')||'<p class="empty">No ideas here yet. Share the first one.</p>'}</div>`:tab==='Expenses'?`<div class="section-head"><div><h2>Shared adventures. Shared expenses.</h2><span class="muted">Keep the money part simple.</span></div><button class="primary" data-action="expense">＋ Add expense</button></div><div class="statrow"><div class="card stat"><small>Total spent</small><strong>${money(total)}</strong><small>${t.expenses.length} shared expenses</small></div><div class="card stat"><small>Per person</small><strong>${money(Math.round(total/t.people.length))}</strong><small>Split across ${t.people.length} travelers</small></div><div class="card stat"><small>Budget remaining</small><strong>${money(t.budget-total)}</strong><small>Of ${money(t.budget)} group budget</small></div></div><div class="filters"><button data-action="expense-list" class="${!balanceView?'active':''}">All expenses</button><button data-action="balances" class="${balanceView?'active':''}">Who owes what</button></div><div class="card table-wrap">${balanceView?`<p class="muted small">Payments minus equal share. Any remaining cents go to travelers in roster order. Positive balances are owed back.</p><table><thead><tr><th>Traveler</th><th>Share</th><th>Balance</th></tr></thead><tbody>${balances(t).map(b=>`<tr><td>${esc(b.name)}</td><td>${money(b.share)}</td><td class="${b.balance>=0?'positive':'negative'}">${b.balance>=0?'+':'−'}${money(Math.abs(b.balance))}</td></tr>`).join('')}</tbody></table>`:`<table><thead><tr><th>Expense</th><th>Paid by</th><th>Split with</th><th>Amount</th></tr></thead><tbody>${t.expenses.map(e=>`<tr><td><strong>${esc(e.description)}</strong><br><span class="muted small">${esc(e.category)}</span></td><td>${esc(e.payer)}</td><td>Everyone</td><td>${money(e.amount)}</td></tr>`).join('')}</tbody></table>${!t.expenses.length?'<p class="empty">No expenses yet.</p>':''}`}</div>`:`<div class="section-head"><div><h2>The group chat, minus the chaos.</h2><span class="muted">Little updates for your next big adventure.</span></div></div><section class="card"><div class="chatbox">${t.chat.map(m=>`<div class="message"><span class="avatar">${esc(m.name[0])}</span><div><strong>${esc(m.name)}</strong> <span class="muted small">${esc(m.time)}</span><p>${esc(m.text)}</p></div></div>`).join('')}</div><form class="chat-form" id="chat"><input name="message" placeholder="Message your trip…" aria-label="Message" maxlength="2000" required><button class="primary">Send ↗</button></form></section>`}<p class="footnote">Saved in this browser · USD · Demo invitations and messages stay on this device. Sign-in does not move or share trip data.</p>`}</main>`;}
const input=(label,name,type='text',value='',extra='')=>`<label class="field" for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra} required>`;
const select=(label,name,values)=>`<label class="field" for="${name}">${label}</label><select id="${name}" name="${name}">${values.map(v=>`<option>${esc(v)}</option>`).join('')}</select>`;
function modal(title,body,submit='Save'){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button type="button" data-action="close" aria-label="Close dialog">×</button></div><form id="dialog-form">${body}<p class="error" role="alert" id="error"></p>${submit?`<div class="actions"><button type="button" data-action="close">Cancel</button><button class="primary">${submit}</button></div>`:''}</form>`;d.showModal();}
function form(kind,id){const t=trip();let body='';if(kind==='new'||kind==='edit'){const x=kind==='edit'?t:{name:'',destination:'',start:'',end:'',budget:0};body=input('Trip name','name','text',x.name,'maxlength="100"')+input('Destination','destination','text',x.destination,'maxlength="150"')+`<div class="row"><div>${input('Start date','start','date',x.start)}</div><div>${input('End date','end','date',x.end)}</div></div>`+input('Group budget (USD)','budget','number',x.budget/100,'min="0" max="100000000" step="0.01"');modal(kind==='new'?'Plan a new trip':'Edit trip details',body,kind==='new'?'Create trip':'Save changes');}
if(kind==='plan')modal('Add a plan',input('Title','title','text','','maxlength="150"')+input('Day','date','date',day,`min="${t.start}" max="${t.end}"`)+input('Time','time','time','18:00')+input('Location or context','location','text','','maxlength="250"')+select('Plan type','type',['Explore','Food & drink','Travel','Stay','Other']),'Add plan');
if(kind==='idea')modal('Share an idea',input('Title','title','text','','maxlength="150"')+'<label class="field" for="description">Description</label><textarea id="description" name="description" maxlength="1000" required></textarea>'+select('Category','category',['Experiences','Stays','Food & drink']),'Share idea');
if(kind==='invite')modal('Bring your people',`<p class="notice">This demo only updates the local trip roster in this browser. No invitation is delivered and no access is granted.</p><p class="small muted">${t.people.map(esc).join(' · ')}</p>`+input('Traveler name','name','text','','maxlength="60"'),'Add traveler');
if(kind==='expense')modal('Add an expense',input('Description','description','text','','maxlength="150"')+input('Amount (USD)','amount','number','','min="0.01" max="100000000" step="0.01"')+select('Paid by','payer',t.people)+select('Category','category',['Food & drink','Stays','Transport','Experiences','Other'])+'<p class="notice">Split equally among everyone in the current roster.</p>','Add expense');
$('#dialog-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{if(kind==='edit'||kind==='new'){const x={...v,budget:Math.round(Number(v.budget)*100)};validate(x,kind==='edit'?t.plans:[]);if(kind==='edit')Object.assign(t,x);else {const n={...x,id:uid(),people:['Drew'],plans:[],ideas:[],expenses:[],chat:[],checklist:seed().checklist.map(c=>({...c,done:false}))};trips.push(n);current=n.id;tab='Overview';day=n.start;}}if(kind==='plan'){if(v.date<t.start||v.date>t.end)throw Error('Choose a day within this trip.');t.plans.push({...v,id:uid()});day=v.date;tab='Itinerary';}if(kind==='idea'){t.ideas.push({...v,id:uid(),votes:0,voted:false});filter='All ideas';tab='Ideas & voting';}if(kind==='invite'){v.name=v.name.trim();if(!v.name||t.people.some(n=>n.toLowerCase()===v.name.toLowerCase()))throw Error('Enter a unique traveler name.');t.people.push(v.name);}if(kind==='expense'){const amount=Math.round(Number(v.amount)*100);if(!Number.isSafeInteger(amount)||amount<=0)throw Error('Enter a positive amount in USD.');t.expenses.push({...v,amount,id:uid()});tab='Expenses';balanceView=false;}$('#modal').close();save();toast('Saved to this browser');}catch(err){$('#error').textContent=err.message;}};}
async function auth(){if(user){modal('Your account',`<p>Signed in as ${esc(user.email)}</p><p class="notice">Trip data is still local. Cross-device saving and collaboration are pending product rules.</p><button type="button" data-action="signout">Sign out</button>`,null);return;}modal('A place for your next adventure',`<p class="notice">Email sign-in is available. Your demo stays in this browser; cross-device saving and group sharing are not enabled yet.</p>${input('Email','email','email','','autocomplete="email"')}${input('Password','password','password','','minlength="6" autocomplete="current-password"')}<p class="muted small">Creating an account? Confirm your email using the link we send before signing in.</p><div class="actions"><button name="intent" value="signup">Create account</button><button class="primary" name="intent" value="signin">Sign in</button></div>`,null);$('#dialog-form').onsubmit=async e=>{e.preventDefault();const intent=e.submitter.value,v=Object.fromEntries(new FormData(e.target));const buttons=[...e.target.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);$('#error').textContent='Connecting…';try{const res=await fetch('https://qhxtazxaspsxztsirquw.supabase.co/auth/v1/'+(intent==='signup'?'signup':'token?grant_type=password'),{method:'POST',headers:{'Content-Type':'application/json',apikey:'sb_publishable_9radPefcC7_lMgrf6FvpqA_YYyvHz0N'},body:JSON.stringify(v)});const data=await res.json();if(!res.ok)throw Error(data.msg||data.error_description||data.message||'Unable to sign in. Try again.');if(intent==='signup'){$('#error').textContent='Check your email and confirm your account before signing in.';}else{user=data.user;$('#modal').close();render();toast('Signed in. Your demo remains local.');}}catch(err){$('#error').textContent=err.message;}finally{buttons.forEach(b=>b.disabled=false);}};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,t=trip();if(a==='close')return $('#modal').close();if(a==='trips'){tab='My trips';render();}if(a==='open'){current=id;tab='Overview';day=trip().start;render();}if(a==='tab'){tab=id;render();}if(a==='day'){day=id;render();}if(a==='filter'){filter=id;render();}if(['new','edit','plan','idea','invite','expense'].includes(a))form(a);if(a==='vote'){const i=t.ideas.find(i=>i.id===id);i.voted=!i.voted;i.votes+=i.voted?1:-1;save();}if(a==='balances'||a==='expense-list'){balanceView=a==='balances';render();}if(a==='detail'){const p=t.plans.find(p=>p.id===id);modal(esc(p.title),`<p>${fmt(p.date)} · ${time(p.time)}</p><p>${esc(p.location)}</p><span class="tag">${esc(p.type)}</span><div class="actions"><button type="button" data-action="remove" data-id="${p.id}">Remove plan</button></div>`,null);}if(a==='remove'){t.plans=t.plans.filter(p=>p.id!==id);$('#modal').close();save();}if(a==='auth')auth();if(a==='signout'){user=null;$('#modal').close();render();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){trip().checklist[Number(e.target.dataset.check)].done=e.target.checked;save();}});
document.addEventListener('submit',e=>{if(e.target.id==='chat'){e.preventDefault();const text=new FormData(e.target).get('message').trim();if(!text)return;trip().chat.push({name:'Drew',text,time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})});save();$('.chatbox').scrollTop=$('.chatbox').scrollHeight;}});
render();
